mapper.select:
SELECT t.tx_id, t.user_id, t.type, t.direction, t.title, t.amount, t.reserved_credits, t.status, t.created_at, t.settled_at, t.kind, t.src_id FROM (
SELECT CONCAT('lot:', l.id) AS tx_id,
CASE l.source WHEN 'purchased' THEN 'recharge' WHEN 'compensation' THEN 'compensation' WHEN 'bonus' THEN 'bonus' WHEN 'daily' THEN 'daily' WHEN 'invite' THEN 'invite' WHEN 'redeem' THEN 'redeem' WHEN 'subscription' THEN 'subscription' WHEN 'gift' THEN 'gift' WHEN 'register' THEN 'gift' ELSE 'gift' END AS type, 'in' AS direction, CASE l.source WHEN 'purchased' THEN '充值到账' WHEN 'compensation' THEN '事故补偿' WHEN 'bonus' THEN '充值赠送' WHEN 'daily' THEN '每日登录赠送' WHEN 'invite' THEN '邀请奖励' WHEN 'redeem' THEN '兑换码兑换' WHEN 'subscription' THEN '会员赠送' WHEN 'gift' THEN '运营赠送' WHEN 'register' THEN '注册赠送' ELSE '积分发放' END AS title, l.amount AS amount,
NULL AS reserved_credits, 'done' AS status, l.gmt_create AS created_at, l.gmt_create AS settled_at, 'grant' AS kind, l.id AS src_id, l.user_id AS user_id FROM billing_credit_lots l
l.user_id = #{userId}
UNION ALL
SELECT CONCAT('res:', r.id) AS tx_id, 'consume' AS type, 'out' AS direction,
CASE WHEN r.title = '' THEN '生成消费' ELSE r.title END AS title, CASE WHEN r.status = 'settled' THEN r.actual_credits ELSE r.reserved_credits END AS amount, r.reserved_credits AS reserved_credits, CASE WHEN r.status = 'settled' THEN 'done' ELSE 'pending' END AS status, r.gmt_create AS created_at, CASE WHEN r.status = 'settled' THEN r.gmt_modified END AS settled_at, 'consume' AS kind, r.id AS src_id, r.user_id AS user_id FROM billing_cost_reservations r WHERE r.status != 'released' AND r.user_id = #{userId}
UNION ALL
SELECT CONCAT('led:', LEFT(e.idempotency_key, CHAR_LENGTH(e.idempotency_key) - CHAR_LENGTH(e.account) - 1)) AS tx_id, CASE e.biz_type WHEN 'expire' THEN 'expire' ELSE 'compensation' END AS type, CASE WHEN SUM(CASE WHEN e.direction = 'credit' THEN e.amount ELSE -e.amount END) >= 0 THEN 'in' ELSE 'out' END AS direction, CASE e.biz_type WHEN 'expire' THEN '积分过期' ELSE '人工调账' END AS title, ABS(SUM(CASE WHEN e.direction = 'credit' THEN e.amount ELSE -e.amount END)) AS amount,
NULL AS reserved_credits, 'done' AS status, MIN(e.gmt_create) AS created_at, MIN(e.gmt_create) AS settled_at, 'ledger' AS kind, MIN(e.id) AS src_id,
MIN(e.user_id) AS user_id FROM billing_ledger_entries e WHERE e.account IN ('wallet', 'frozen') AND e.idempotency_key LIKE CONCAT('%:', e.account) AND e.biz_type IN ('expire', 'adjust') AND e.user_id = #{userId} GROUP BY tx_id, e.biz_type HAVING SUM(CASE WHEN e.direction = 'credit' THEN e.amount ELSE -e.amount END) != 0
) t
(t.created_at < #{cursorTime} OR (t.created_at = #{cursorTime} AND (t.kind > #{cursorKind} OR (t.kind = #{cursorKind} AND t.src_id < #{cursorId}))))
AND t.type = #{typeFilter}
ORDER BY t.created_at DESC, t.kind ASC, t.src_id DESC LIMIT #{limit}
